import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            toml_config = tomllib.load(f)
            config.update(tomllib_config)
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_keys = key[len(env_prefix)+1:].split('__')
            current = config
            for k in nested_keys[:-1]:
                if k not in current:
                    current[k] = {}
                current = current[k]
            current[nested_keys[-1]] = _coerce(value)
    return config

def _coerce(value):
    if value.isdigit():
        return int(value)
    if value.lower() in ('true', 'yes', '1'):
        return True
    if value.lower() in ('false', 'no', '0'):
        return False
    return value

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 'two'}
    assert load_config(defaults) == defaults

def test_toml_file(tmp_path):
    toml_file = tmp_path / 'config.toml'
    toml_file.write_text('a = 3\nb = "three"')
    assert load_config({'a': 1, 'b': 'two'}, toml_file=str(toml_file)) == {'a': 3, 'b': 'three'}

def test_env_variables(tmp_path):
    env = {'APP__A': '4', 'APP__B': 'four'}
    assert load_config({'a': 1, 'b': 'two'}, env_prefix='APP', env_mapping=env) == {'a': 4, 'b': 'four'}

def test_nested_keys(tmp_path):
    env = {'APP__SERVER__PORT': '8080'}
    assert load_config({'server': {'port': 80}}, env_prefix='APP', env_mapping=env) == {'server': {'port': 8080}}

def test_coercion():
    env = {'APP__A': '5', 'APP__B': 'true', 'APP__C': 'false'}
    assert load_config({'a': 1, 'b': False, 'c': True}, env_prefix='APP', env_mapping=env) == {'a': 5, 'b': True, 'c': False}

def test_missing_file(tmp_path):
    toml_file = tmp_path / 'config.toml'
    assert load_config({'a': 1}, toml_file=str(toml_file)) == {'a': 1}

def test_missing_default():
    env = {'APP__A': '5'}
    with pytest.raises(ConfigError):
        load_config({}, env_prefix='APP', env_mapping=env)

def test_coercion_error():
    env = {'APP__A': 'five'}
    with pytest.raises(ConfigError):
        load_config({'a': 1}, env_prefix='APP', env_mapping=env)

